namespace sv_e2cd33886a50499f83e1491320b94674.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    background: #fafafa;
    align-self: flex-start;
}

.catalog-sidebar h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

.catalog-sidebar h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.4rem;
    cursor: pointer;
}

.price-inputs {
    display: flex;
    gap: 0.75rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

.price-inputs input {
    width: 80px;
    padding: 0.3rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background: transparent;
    border: 1px solid #6c757d;
    border-radius: 4px;
    cursor: pointer;
    color: #6c757d;
}

.btn-clear:hover {
    background: #f8f9fa;
}

/* Main content */
.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.4rem 0.6rem;
